//! GENERATED by the milestone-6 golden capture -- do not hand-edit.
//!
//! Every value below is the reference engine's own output. `placeAnchors`,
//! `buildPrimaries` and `buildPrimariesFromPaths` are on neither `UME`'s public
//! export nor its `_test` one, so the capture adds them (with `buildSite` and
//! `makeGraph`) to the returned object by a single anchored replacement of the
//! `return {` line, asserted to match exactly once. The frozen reference file
//! itself is untouched.
//!
//! Rasters are emitted here rather than rebuilt on the Rust side, so both sides
//! provably run on identical inputs. Points are flat `[x, y, x, y, ...]`.
//!
//! `grid_hash` is the reference's OWN `fnv1a` over its own grid dump
//! (`"cx:cy=id,id;..."`, cells sorted by that string key, empty cells dropped):
//! the spatial index is milestone 2's and is golden-verified there, so this
//! milestone pins it exactly without restating tens of thousands of cells.

#![allow(clippy::approx_constant, clippy::unreadable_literal)]

/// A water raster + centreline, exactly as the capture handed it to `buildSite`.
pub struct WaterSpec {
    pub mask: &'static [u8],
    pub dt: &'static [f64],
    pub mw: usize,
    pub mh: usize,
    pub cell_m: f64,
    pub river_path: Option<&'static [f64]>,
    pub river_width_m: f64,
    pub river_order: f64,
    pub sea_lake_cells: f64,
}

/// A heightfield raster, likewise.
pub struct TerrainSpec {
    pub grid: &'static [f64],
    pub mw: usize,
    pub mh: usize,
    pub cell_m: f64,
    pub h_min: f64,
    pub h_max: f64,
}

/// One captured scenario.
pub struct Case {
    pub name: &'static str,
    // --- inputs ---
    pub site_seed: u32,
    pub kind: &'static str,
    pub anchor_seed: u32,
    pub wm: f64,
    pub hm: f64,
    pub water: Option<&'static WaterSpec>,
    pub terrain: Option<&'static TerrainSpec>,
    /// `None` drives `buildPrimaries`; `Some` drives `buildPrimariesFromPaths`
    /// with these metre-offset polylines.
    pub paths: Option<&'static [&'static [f64]]>,
    // --- captured output ---
    pub market: (f64, f64),
    pub prov: &'static str,
    /// One entry per route, flat `[x, y, ...]`.
    pub route_pts: &'static [&'static [f64]],
    /// The route's `i` field; `-1` where the reference pushed no `i` at all.
    pub route_i: &'static [i64],
    /// `(x, y, adj)`
    pub nodes: &'static [(f64, f64, &'static [usize])],
    /// `(a, b, cls, w, epoch, alive)`
    pub edges: &'static [(usize, usize, &'static str, f64, i32, bool)],
    pub grid_cells: usize,
    pub grid_hash: u32,
    pub from_paths: bool,
    // --- site facts the gate asserted, re-asserted on the Rust side ---
    pub route_ends: &'static [f64],
    pub has_bridge: bool,
    pub has_quay: bool,
}

